sp_ListarPedido	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarPedido`(p_idEmpresa INT)\nBEGIN\n\n    SELECT\n\n        p.idPedido,\n\n        p.numeroPedido,\n\n        p.cliente_id   AS idCliente,\n\n        c.nome         AS nomeCliente,\n\n        p.idEmpresa,\n\n        p.canal,\n\n        p.numeroExterno,\n\n        sp.Nome        AS status,\n\n        p.statusPedido_id,\n\n        p.Observacao   AS observacao,\n\n        p.valorTotal,\n\n        p.valorFrete,\n\n        p.Desconto     AS desconto,\n\n        p.dthPedido    AS dthCriacao,\n\n        (SELECT COUNT(*) FROM PedidoItem pi WHERE pi.idPedido = p.idPedido) AS totalItens\n\n    FROM Pedido p\n\n    INNER JOIN Cliente c ON c.idCliente = p.cliente_id\n\n    INNER JOIN StatusPedido sp ON sp.idStatusPedido = p.statusPedido_id\n\n    WHERE p.idEmpresa = p_idEmpresa\n\n    ORDER BY p.dthPedido DESC;\n\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
